/// <summary>
/// Duplicate of method <c>allowStateTransition</c> due to it being internal.
/// </summary>
/// <param name = "_message">Message.</param>
/// <param name = "_nextState">Next state.</param>
/// <returns>True if allowed; otherwise, false.</returns>
public boolean metAllowStateTransition(SysMessage _message, SysMessageState _nextState)
{
    // Std code returns true from SysMessageTargetInstanceTypeMetadata\isRunningOnTarget
    /*if (!this.metIsRunningOnMessageTarget(_message))
    {
        return false;
    }*/

    SysMessageStateTransition desiredStateTransition = SysMessageStateTransition::newFromStates(_message.messageProcessingState().State, _nextState);

    Enumerator enumerator = this.getAllowedMessageStateTransitions();
    while (enumerator.moveNext())
    {
        if (desiredStateTransition.isEqual(enumerator.current()))
        {
            return true;
        }
    }

    return false;
}

/// <summary>
/// Duplicate of method <c>isRunningOnMessageTarget</c> due to it being internal.
/// </summary>
/// <param name = "_message">Message.</param>
/// <returns>True if it's running; otherwise, false.</returns>
public boolean metIsRunningOnMessageTarget(SysMessage _message)
{
    boolean ret; 

    if (_message.MessageTarget)
    {
        SysMessageTarget messageTarget = SysMessageTarget::find(_message.MessageTarget);

        SysMessageTargetInstanceTypeMetadata messageTargetInst =  SysMessageTargetInstanceTypeMetadata::construct(messageTarget.InstanceRelationType);
        TableName tableName = tableId2Name(messageTarget.InstanceRelationType);
        ret = (tableName == tableStr(SysWorkloadMessageHubCompanyTarget) || tableName == tableStr(SysWorkloadMessageCompanyTarget));

    }

    return ret;
}
